<?php
namespace App\\Services;
use App\\Repositories\\AppointmentRepository;use App\\Repositories\\ClinicRepository;use App\\Repositories\\PatientRepository;use App\\Repositories\\ReminderRepository;use Illuminate\\Support\\Str;use Illuminate\\Support\\Carbon;use Illuminate\\Support\\Facades\\DB;use Symfony\\Component\\HttpKernel\\Exception\\NotFoundHttpException;use Symfony\\Component\\HttpKernel\\Exception\\BadRequestHttpException;use Symfony\\Component\\HttpKernel\\Exception\\ConflictHttpException;
class AppointmentService{
 public function __construct(private AppointmentRepository $appointments,private ClinicRepository $clinics,private PatientRepository $patients,private ReminderRepository $reminders){}
 public function create(array $d):array{$clinic=$this->clinics->find($d['clinicId']);$patient=$this->patients->find($d['patientId']);if(!$clinic||!$patient)throw new NotFoundHttpException('La clínica o el paciente no existen');if($patient->clinic_id!==$clinic->id)throw new BadRequestHttpException('El paciente no pertenece a la clínica');$start=Carbon::parse($d['startsAt']);if(!$start->isFuture())throw new BadRequestHttpException('La cita debe ser futura');return DB::transaction(function()use($clinic,$patient,$start){$a=$this->appointments->create(['id'=>(string)Str::uuid(),'clinic_id'=>$clinic->id,'patient_id'=>$patient->id,'starts_at'=>$start,'status'=>'scheduled']);$this->makeReminder($a,$clinic,$patient);return $this->serialize($this->appointments->find($a->id));});}
 public function get(string $id):array{$a=$this->appointments->find($id);if(!$a)throw new NotFoundHttpException('No existe');return $this->serialize($a);}
 public function reschedule(string $id,array $d):array{return DB::transaction(function()use($id,$d){$a=$this->appointments->lock($id);if(!$a)throw new NotFoundHttpException('No existe');if($a->status==='cancelled'||$a->starts_at->isPast())throw new ConflictHttpException('La cita está cancelada o ya empezó');$start=Carbon::parse($d['startsAt']);if(!$start->isFuture())throw new BadRequestHttpException('La cita debe ser futura');$this->reminders->cancelPriorForReschedule($a->id);$a->starts_at=$start;$a->status='scheduled';$a->save();$this->makeReminder($a,$a->clinic,$a->patient);return $this->serialize($this->appointments->find($a->id));});}
 public function cancel(string $id):array{return DB::transaction(function()use($id){$a=$this->appointments->lock($id);if(!$a)throw new NotFoundHttpException('No existe');if($a->status!=='cancelled'){$a->status='cancelled';$a->save();$this->reminders->cancelPending($a->id);}return $this->serialize($this->appointments->find($id));});}
 private function makeReminder($a,$clinic,$patient):void{$start=$a->starts_at->copy()->setTimezone($clinic->timezone);$due=$start->subDay();if($due->hour>=21||$due->hour<9)$due->setTime(9,0);$now=now()->setTimezone($clinic->timezone);if($due->lessThan($now)){$due=$now->copy();if($due->hour>=21||$due->hour<9)$due->setTime(9,0);} $skip=null;$status='pending';if(!$due->lessThan($a->starts_at->setTimezone($clinic->timezone))){$status='skipped';$skip='too_late';}elseif(!$patient->phone){$status='skipped';$skip='no_phone';}elseif(!$patient->accepts_reminders){$status='skipped';$skip='opted_out';}$this->reminders->create(['id'=>(string)Str::uuid(),'appointment_id'=>$a->id,'scheduled_for'=>$due->utc(),'status'=>$status,'attempts'=>0,'skip_reason'=>$skip,'idempotency_key'=>'reminder-'.$a->id.'-'.Str::uuid()]);}
 private function serialize($a):array{return ['id'=>$a->id,'clinicId'=>$a->clinic_id,'patientId'=>$a->patient_id,'startsAt'=>$a->starts_at->utc()->toISOString(),'status'=>$a->status,'reminders'=>$a->reminders->map(fn($r)=>['id'=>$r->id,'scheduledFor'=>$r->scheduled_for->utc()->toISOString(),'status'=>$r->status,'attempts'=>$r->attempts,'sentAt'=>$r->sent_at?->utc()->toISOString(),'skipReason'=>$r->skip_reason])->values()->all()];}
}